package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OidcClaimMappingVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property oidc claim mapping of tenant login provider ")
  void test_oidc_claim_mapping_v_o_builder() {
    Assertions.assertFalse(OidcClaimMappingVO.nullValue().getOidcClaimMapping().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(OidcClaimMappingVO.tryFrom(null).getOidcClaimMapping().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        OidcClaimMappingVO.from("one").getOidcClaimMapping().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> OidcClaimMappingVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OidcClaimMappingVO.from("one").toString());
  }
}
